"use strict";
const {Store,hash,uuid,model}=require('./store.cjs');
const fail=x=>{throw Error(x);};
class Controller {
 constructor(store,provider,authority=null){this.store=store;this.provider=provider;this.authority=authority;this.generation=uuid();this.epoch=0;this.closed=false;this.busy=false;this.listeners=new Set();this.previews=new Map();this.cache=null;}
 invalidate(){this.epoch++;this.cache=null;this.previews.clear();for(const f of this.listeners){try{f();}catch{}}}
 close(){this.closed=true;this.invalidate();this.listeners.clear();}
 guard(epoch){if(this.closed)fail('service-closed');if(epoch!==this.epoch)fail('service-invalidated');}
 async work(fn){if(this.closed)fail('service-closed');if(this.busy)fail('service-busy');this.busy=true;const epoch=this.epoch;try{return await fn(()=>this.guard(epoch));}finally{this.busy=false;}}
 preview(data){if(this.previews.size>=16)this.previews.clear();const token=uuid();this.previews.set(token,JSON.parse(JSON.stringify({...data,epoch:this.epoch})));return JSON.parse(JSON.stringify({token,...data}));}
 take(token,kind){const p=this.previews.get(token);if(!p||p.kind!==kind)fail('preview-expired');this.guard(p.epoch);return p;}
 view(c,frame){return JSON.parse(JSON.stringify({contextId:c.contextId,registeredLabel:c.canonicalLabel,subjects:c.subjects,bindings:c.bindings,observation:frame.observations[c.contextId],authority:'identity-registry',nameAuthority:c.naming?.authority==='center'?'center':'owner',eligibilityAuthority:'owner'}));}
 read(options={}){this.guard(this.epoch);const active=!!this.authority?.writing;const signature=this.store.signature();const changed=this.signature!==undefined&&signature!==this.signature;this.signature=signature;if(changed)this.invalidate();if(options.refresh||active||this.wasActive)this.cache=null;this.wasActive=active;if(!this.cache){const s=this.authority?this.authority.readView():this.store.status();if(s.status!=='ready')return {ok:false,reason:s.status};this.cache=s.frame;}const f=this.cache,limit=options.limit??100;if(!Number.isInteger(limit)||limit<1||limit>100)fail('page-limit-invalid');const stamp=`${this.generation}:${this.epoch}:${f.state.revision}`;let offset=0;if(options.cursor){const c=JSON.parse(Buffer.from(options.cursor,'base64').toString());if(c.stamp!==stamp||!Number.isInteger(c.offset)||c.offset<0||c.offset>f.state.contexts.length)fail('cursor-stale');offset=c.offset;}const items=f.state.contexts.slice(offset,offset+limit).map(c=>this.view(c,f));return {ok:true,contractVersion:1,snapshotType:'registered-identity-session-snapshot',namespace:f.state.namespace,revision:f.state.revision,generation:this.generation,epoch:this.epoch,total:f.state.contexts.length,items,cursor:offset+limit<f.state.contexts.length?Buffer.from(JSON.stringify({stamp,offset:offset+limit})).toString('base64'):null};}
 get(id){const result=this.read();if(!result.ok)return result;const c=this.cache.state.contexts.find(c=>c.contextId===id);return {ok:true,item:c?this.view(c,this.cache):null};}
 exact(ref){const result=this.read();if(!result.ok)return result;const fn=ref.subject?model.subjectKey:model.bindingKey,key=fn(ref.subject||ref.binding);const c=this.cache.state.contexts.find(c=>(ref.subject?c.subjects:c.bindings).some(x=>fn(x)===key));return {ok:true,item:c?this.view(c,this.cache):null};}
 resolve(query){const result=this.read();if(!result.ok)return result;return {ok:true,...model.resolveLegacy(this.cache.version===3?this.cache.state:require('./naming-model.cjs').bare(this.cache.version===6?require('./binding-model.cjs').prior(this.cache.state):this.cache.state),query)};}
 previewInitialize(){this.guard(this.epoch);const s=this.store.status();if(s.status!=='unconfigured')fail(s.status==='ready'?'already-initialized':s.status);return this.preview({kind:'initialize',namespace:'registry_'+uuid(),digest:s.digest});}
 confirmInitialize(token){return this.work(async guard=>{const p=this.take(token,'initialize');const result=this.store.initialize(p.namespace,p.digest,guard);this.invalidate();return {ok:true,namespace:result.state.namespace};});}
 previewRegistration(row){return this.work(async guard=>{const status=this.store.status();if(status.status!=='ready')fail(status.status);if(status.frame.version!==3)fail('legacy-registration-retired-use-center-management');const evidence=await this.provider.observe(row,()=>{try{guard();return true;}catch{return false;}});guard();const existing=status.frame.state.contexts.find(c=>model.subjectKey(c.subjects[0])===model.subjectKey(evidence.subject));const added=existing?evidence.bindings.filter(b=>!existing.bindings.some(x=>model.bindingKey(x)===model.bindingKey(b))):evidence.bindings;if(existing&&!added.length)return {kind:'existing',item:this.view(existing,status.frame)};const command={kind:existing?'bind':'register',namespace:status.frame.state.namespace,expectedRevision:status.frame.state.revision,requestId:`r${status.frame.state.revision}_${uuid()}`,contextId:existing?.contextId||'ctx_'+uuid(),canonicalLabel:row.label,subjects:existing?[]:[evidence.subject],bindings:added};this.store.next(status.frame,command,evidence.observation);return this.preview({kind:'register',row:evidence.row,digest:status.digest,evidenceDigest:evidence.digest,command,observation:evidence.observation});});}
 confirmRegistration(token){return this.work(async guard=>{const p=this.take(token,'register');const evidence=await this.provider.observe(p.row,()=>{try{guard();return true;}catch{return false;}});guard();if(evidence.digest!==p.evidenceDigest)fail('owner-evidence-changed');try{const frame=this.store.commit(p.command,evidence.observation,p.digest,()=>{guard();evidence.guard();});return {ok:true,item:this.view(frame.state.contexts.find(c=>c.contextId===p.command.contextId),frame)};}finally{this.invalidate();}});}
 previewRecovery(){this.guard(this.epoch);return this.preview({kind:'recovery',plan:this.store.previewRecovery()});}
 confirmRecovery(token){return this.work(async guard=>{const p=this.take(token,'recovery');let evidence;if(p.plan.needsProvider){const row=p.plan.pending.observation.row;if(!row)fail('pending-provider-reference-missing');evidence=await this.provider.observe(row,()=>{try{guard();return true;}catch{return false;}});if(evidence.observation.digest!==p.plan.pending.observation.digest)fail('pending-owner-evidence-changed');}try{const frame=this.store.recover(p.plan,()=>{guard();evidence?.guard();});return {ok:true,namespace:frame.state.namespace,revision:frame.state.revision};}finally{this.invalidate();}});}
}
module.exports={Controller};
